n=22; bg=1; out=[[bg]*n for _ in range(n)]
tiles=[(3,0,8,6),(5,17,2,5),(9,12,2,4),(12,5,8,7),(16,0,8,2),(17,17,2,6)]
for r,c,border,fill in tiles:
    for dr in range(5):
        for dc in range(5):
            out[r+dr][c+dc] = border if dr in (0,4) or dc in (0,4) else fill
print('\n'.join(' '.join(map(str,row)) for row in out))
